// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, bytes32 adminRole) public {
        vm.assume(role != bytes32(0));
        vm.assume(adminRole != bytes32(0));

        vm.assume(role == c.TIMELOCK_ADMIN_ROLE() || role == c.PROPOSER_ROLE() || role == c.EXECUTOR_ROLE());

        bytes32 expectedAdmin = c.TIMELOCK_ADMIN_ROLE();
        bytes32 actualAdmin = c.getRoleAdmin(role);
        assertTrue(actualAdmin == expectedAdmin);
    }
}
